-- V39/V40

-- Restores the original single-column FK (same name and ON DELETE) and drops the composite FK.
create or replace function pg_temp.from_tenant_fk(
    p_child regclass, p_col name, p_parent regclass, p_old name, p_new name, p_on_delete text)
returns void language plpgsql as $fn$
begin
    if not exists (select 1 from pg_constraint where conrelid = p_child and conname = p_old) then
        execute format('alter table %s add constraint %I foreign key (%I) references %s (id) on delete %s',
                       p_child, p_old, p_col, p_parent, p_on_delete);
    end if;
    execute format('alter table %s drop constraint if exists %I', p_child, p_new);
end
